<?php
$pageTitle='Account'; require_once __DIR__.'/includes/header.php'; $ok=$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=$pdo->prepare("SELECT password_hash FROM users WHERE id=?");$st->execute([user()['id']]);$hash=$st->fetchColumn();
if(!password_verify($_POST['current_password'],$hash)){$err='Current password is incorrect.';}elseif(strlen($_POST['new_password'])<10){$err='New password must be at least 10 characters.';}elseif(!preg_match('/[A-Z]/',$_POST['new_password'])||!preg_match('/[a-z]/',$_POST['new_password'])||!preg_match('/\d/',$_POST['new_password'])){$err='Use at least 10 characters with uppercase, lowercase and a number.';}elseif($_POST['new_password']!==$_POST['confirm_password']){$err='Passwords do not match.';}else{$pdo->prepare("UPDATE users SET password_hash=?,must_change_password=0,failed_login_attempts=0,locked_until=NULL WHERE id=?")->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),user()['id']]);$_SESSION['user']['must_change_password']=0;audit($pdo,'change_password','users',user()['id']);$ok='Password changed successfully.';}}
?><h2>Account Security</h2><?php if(isset($_GET['first'])): ?><div class="alert alert-warning">Your administrator issued a first-time password. Change it now before continuing.</div><?php endif;?><?php if($ok): ?><div class="alert alert-success"><?=e($ok)?></div><?php endif;?><?php if($err): ?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><div class="card p-4 col-lg-6"><form method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="mb-3"><label>Current password</label><input class="form-control" type="password" name="current_password" required autocomplete="current-password"></div><div class="mb-3"><label>New password</label><input class="form-control" type="password" name="new_password" minlength="10" required autocomplete="new-password"><div class="form-text">At least 10 characters, including uppercase, lowercase and a number.</div></div><div class="mb-3"><label>Confirm new password</label><input class="form-control" type="password" name="confirm_password" required autocomplete="new-password"></div><button class="btn btn-primary">Change password</button></form></div><?php require __DIR__.'/includes/footer.php';
